(4, 1, 3328, '{\"id\":3328,\"name\":\"The Witcher 3: Wild Hunt\",\"slug\":\"the-witcher-3-wild-hunt\",\"description\":\"The third game in a series, it holds nothing back from the player. Open world adventures of the renowned monster slayer Geralt of Rivia are now even on a larger scale. Following the source material more accurately, this time Geralt is trying to find the child of the prophecy, Ciri while making a quick coin from various contracts on the side. Great attention to the world building above all creates an immersive story, where your decisions will shape the world around you.\\n\\nCD Project Red are infamous for the amount of work they put into their games, and it shows, because aside from classic third-person action RPG base game they provided 2 massive DLCs with unique questlines and 16 smaller DLCs, containing extra quests and items.\\n\\nPlayers praise the game for its atmosphere and a wide open world that finds the balance between fantasy elements and realistic and believable mechanics, and the game deserved numerous awards for every aspect of the game, from music to direction.\",\"released\":\"2015-05-18\",\"background_image\":\"https://media.rawg.io/media/games/618/618c2031a07bbff6b4f611f10b6bcdbc.jpg\",\"rating\":4.64,\"rating_top\":5,\"metacritic\":92,\"playtime\":43,\"esrb_rating\":\"Mature\",\"website\":\"https://thewitcher.com/en/witcher3\",\"platforms\":[{\"platform\":{\"id\":187,\"name\":\"PlayStation 5\",\"slug\":\"playstation5\"}},{\"platform\":{\"id\":186,\"name\":\"Xbox Series S/X\",\"slug\":\"xbox-series-x\"}},{\"platform\":{\"id\":5,\"name\":\"macOS\",\"slug\":\"macos\"}},{\"platform\":{\"id\":18,\"name\":\"PlayStation 4\",\"slug\":\"playstation4\"}},{\"platform\":{\"id\":7,\"name\":\"Nintendo Switch\",\"slug\":\"nintendo-switch\"}},{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":1,\"name\":\"Xbox One\",\"slug\":\"xbox-one\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":5,\"na