(6, 1, 5679, '{\"id\":5679,\"name\":\"The Elder Scrolls V: Skyrim\",\"slug\":\"the-elder-scrolls-v-skyrim\",\"description\":\"The fifth game in the series, Skyrim takes us on a journey through the coldest region of Cyrodiil. Once again player can traverse the open world RPG armed with various medieval weapons and magic, to become a hero of Nordic legends –Dovahkiin, the Dragonborn. After mandatory character creation players will have to escape not only imprisonment but a fire-breathing dragon. Something Skyrim hasn’t seen in centuries.\",\"released\":\"2011-11-11\",\"background_image\":\"https://media.rawg.io/media/games/7cf/7cfc9220b401b7a300e409e539c9afd5.jpg\",\"rating\":4.42,\"rating_top\":5,\"metacritic\":94,\"playtime\":46,\"esrb_rating\":\"Mature\",\"website\":\"http://elderscrolls.com/\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":186,\"name\":\"Xbox Series S/X\",\"slug\":\"xbox-series-x\"}},{\"platform\":{\"id\":187,\"name\":\"PlayStation 5\",\"slug\":\"playstation5\"}},{\"platform\":{\"id\":1,\"name\":\"Xbox One\",\"slug\":\"xbox-one\"}},{\"platform\":{\"id\":18,\"name\":\"PlayStation 4\",\"slug\":\"playstation4\"}},{\"platform\":{\"id\":7,\"name\":\"Nintendo Switch\",\"slug\":\"nintendo-switch\"}},{\"platform\":{\"id\":14,\"name\":\"Xbox 360\",\"slug\":\"xbox360\"}},{\"platform\":{\"id\":16,\"name\":\"PlayStation 3\",\"slug\":\"playstation3\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-rpg\"}],\"developers\":[{\"id\":4207,\"name\":\"Bethesda Game Studios\",\"slug\":\"bethesda-game-studios\"}],\"publishers\":[{\"id\":339,\"name\":\"Bethesda Softworks\",\"slug\":\"bethesda-softworks\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":40849,\"name\":\"Steam Cloud\",\"slug\":\"steam-cloud\"},{\"id\":13,\"name\":\"Atmosph