(11, 1, 244700, '{\"id\":244700,\"name\":\"OMORI\",\"slug\":\"omori\",\"description\":\"OMORI is a surreal psychological horror RPGmaker game. You must travel between two worlds, both welcoming, both concealing the same secrets. Meet new (old) people, fight new (old) enemies, explore your own memories, and uncover some hidden truths along the way (although you wish you hadn\'t.) When the time comes, you can only choose one. \\n\\nWhich world is more real? You decide, I guess.\",\"released\":\"2020-12-25\",\"background_image\":\"https://media.rawg.io/media/games/2cb/2cb0d8e4cb57e7b03576619be68326c8.jpg\",\"rating\":4.35,\"rating_top\":5,\"playtime\":6,\"esrb_rating\":\"Not Rated\",\"platforms\":[{\"platform\":{\"id\":7,\"name\":\"Nintendo Switch\",\"slug\":\"nintendo-switch\"}},{\"platform\":{\"id\":5,\"name\":\"macOS\",\"slug\":\"macos\"}},{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":186,\"name\":\"Xbox Series S/X\",\"slug\":\"xbox-series-x\"}}],\"genres\":[{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-rpg\"},{\"id\":40,\"name\":\"Casual\",\"slug\":\"casual\"},{\"id\":51,\"name\":\"Indie\",\"slug\":\"indie\"}],\"developers\":[{\"id\":145690,\"name\":\"OMOCAT\",\"slug\":\"omocat-llc\"}],\"publishers\":[{\"id\":2163,\"name\":\"Playism\",\"slug\":\"playism\"},{\"id\":39074,\"name\":\"OMOCAT\",\"slug\":\"omocat-llc\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":24,\"name\":\"RPG\",\"slug\":\"rpg\"},{\"id\":40845,\"name\":\"Partial Controller Support\",\"slug\":\"partial-controller-support\"}],\"screenshots\":[{\"id\":1643926,\"image\":\"https://media.rawg.io/media/screenshots/6c7/6c70a497fb2c569b47859aacfef43622.jpg\"},{\"id\":1643927,\"image\":\"https://media.rawg.io/media/screenshots/149/149a3c989cc70a864e9ca457f09534ac.jpg\"},{\"id\":1643928,\"image\":\"https://media.rawg.io/media/screenshots/9f5/9f5e8dd13e78f23f39739f81a40c1a76.jpg\"},{\"id\":1643929,\"image\":\"https://media.rawg.io/media/screenshots/037/037001dd880201932c994494dc7be6d7.jpg\"},{\"id\":1643930,\"image\":\"https://media.rawg.io/media/screenshots/575/575c3f012925e228f946a4101b6619ea.jpg\"},{\"id\":1643931,\"image\":\"https://media.rawg.io/media/screenshots/3de/3de80c2230adea8d1a2f05d4b70fac98.jpg\"}],\"series\":[],\"stores\":[{\"id\":362016,\"store\":{\"id\":1,\"name\":\"Steam\",\"domain\":\"store.steampowered.com\"}}]}', '2026-01-30 13:57:56'),
(12, 1, 3751, '{\"id\":3751,\"name\":\"Dark Souls II\",\"slug\":\"dark-souls-ii\",\"description\":\"Dark Souls II is the third installment in the well-known Souls series. It’s a different game from all the others because of its directors. With Dark Souls II the main director and founder of Souls-like genre Hidetaka Miyazaki took place only as a supervisor of the project, leaving a place of the director of the game for two young video game designers Tomohiro Shibuya and Yui Tanimura. One could ask if the game is as good and beautiful as other past games in the Series and the answer would be that Dark Souls II is different yet deep and unforgiving as all the other titles in the series. The famous difficulty of previous games is still there but the world is much simpler yet connected and dangerous. Enemies still respond after death of a player but only about 15 times. After that they disappear forever. Boss battles are much simpler, this time focuses on many simpler bosses at a time instead of one powerful boss. \\nDark Souls II is one of those games which were painfully downgraded in a favor of hardware of consoles, that means that players got less graphically advanced version than promised. Yet the game is interesting and deep and it’s definitely a must play for every Souls fan.\",\"released\":\"2014-03-11\",\"background_image\":\"https://media.rawg.io/media/games/651/6512783a214618584d144d5d852ba595.jpg\",\"rating\":4.03,\"rating_top\":4,\"playtime\":43,\"esrb_rating\":\"Mature\",\"platforms\":[{\"platform\":{\"id\":18,\"name\":\"PlayStation 4\",\"slug\":\"playstation4\"}},{\"platform\":{\"id\":1,\"name\":\"Xbox One\",\"slug\":\"xbox-one\"}},{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":14,\"name\":\"Xbox 360\",\"slug\":\"xbox360\"}},{\"platform\":{\"id\":16,\"name\":\"PlayStation 3\",\"slug\":\"playstation3\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-r