(136, 6, 329894, '{\"id\":329894,\"name\":\"Shield Ninja - Teo Ripka\",\"slug\":\"shield-ninja-teo-ripka\",\"description\":\"<p>Shield Ninja - Teo Ripka is a game developed by manicka. It was originally released in 2019. <br>Shield Ninja - Teo Ripka is available on Web. The game is sold via itch.io. </p>\\n\\n<p></p>\",\"released\":\"2019-06-23\",\"background_image\":\"https://media.rawg.io/media/screenshots/951/951bf68641d2794714cbcd9c84ccdeb2.jpg\",\"rating\":0,\"rating_top\":0,\"metacritic\":null,\"playtime\":0,\"esrb_rating\":\"Not Rated\",\"website\":\"\",\"platforms\":[{\"platform\":{\"id\":171,\"name\":\"Web\",\"slug\":\"web\"}}],\"genres\":[],\"developers\":[{\"id\":131943,\"name\":\"manicka\",\"slug\":\"manicka\"}],\"publishers\":[],\"tags\":[],\"screenshots\":[{\"id\":1972036,\"image\":\"https://media.rawg.io/media/screenshots/951/951bf68641d2794714cbcd9c84ccdeb2.jpg\"}],\"series\":[],\"stores\":[{\"id\":331861,\"store\":{\"id\":9,\"name\":\"itch.io\",\"domain\":\"itch.io\"}}]}', '2026-01-30 11:15:06'),
(137, 6, 45794, '{\"id\":45794,\"name\":\"Pixel Traffic: Risky Bridge\",\"slug\":\"pixel-traffic-risky-bridge\",\"description\":\"Risky Bridge is the second game in the \\\"Pixel Traffic\\\" series. This game develops your mental attention, dexterity and sharpness. Stop the moving bridge and drive the car along the entire route.Game features:Easy controls\\nNice pixel graphics\\nMany cool achievements\\nCollect coins and exchange them for any of the 30 new vehicles. You\'ll have only one chance to attach a road block on the bridge, and if it is crooked, you can say goodbye to your car. As you progress through the game, the difficulty and the number of blocks will only increase. Develop your skills at any of the two game levels!\\nSo, you\'re already a pro and have gotten the first achievements? Don\'t get cocky, because maybe one of your friends already beat you to it, and got all the rewards!\",\"released\":\"2017-09-06\",\"background_image\":\"https://media.rawg.io/media/screenshots/d40/d40c1a62d5f9e03b5a7c7a9a107ac99e.jpg\",\"rating\":0,\"rating_top\":0,\"metacritic\":null,\"playtime\":1,\"esrb_rating\":\"Not Rated\",\"website\":\"\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":5,\"name\":\"macOS\",\"slug\":\"macos\"}},{\"platform\":{\"id\":6,\"name\":\"Linux\",\"slug\":\"linux\"}}],\"genres\":[{\"id\":1,\"name\":\"Racing\",\"slug\":\"racing\"},{\"id\":40,\"name\":\"Casual\",\"slug\":\"casual\"},{\"id\":51,\"name\":\"Indie\",\"slug\":\"indie\"}],\"developers\":[{\"id\":21808,\"name\":\"For Kids\",\"slug\":\"for-kids\"}],\"publishers\":[{\"id\":16567,\"name\":\"For Kids\",\"slug\":\"for-kids\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":40850,\"name\":\"Steam Leaderboards\",\"slug\":\"steam-leaderboards\"},{\"id\":107,\"name\":\"Family Friendly\",\"slug\":\"family-friendly\"}],\"screenshots\":[{\"id\":651752,\"image\":\"https://media.rawg.io/media/screenshots/181/181ecc473b8b24cf085a698b5e304f67.jpg\"},{\"id\":651753,\"image\":\"https://media.rawg.io/media/screenshots/ea9/ea964195b50aad18f84f31deeb51d5b7.jpg\"},{\"id\":651754,\"image\":\"https://media.rawg.io/media/screenshots/c61/c617f272fbab962e871652f9f94b226e.jpg\"},{\"id\":651755,\"image\":\"https://media.rawg.io/media/screenshots/b41/b416314bbdd0064c0a522953ce004b17.jpg\"},{\"id\":651756,\"image\":\"https://media.rawg.io/media/screenshots/e0e/e0efd7689a6384f06ebec685ea06a713.jpg\"},{\"id\":651757,\"image\":\"https://media.rawg.io/media/screenshots/d40/d40c1a62d5f9e03b5a7c7a9a107ac99e.jpg\"}],\"series\":[],\"stores\":[{\"id\":37592,\"store\":{\"id\":1,\"name\":\"Steam\",\"domain\":\"store.steampowered.com\"}}]}', '2026-01-30 11:25:24'),
(138, 6, 1015456, '{\"id\":1015456,\"name\":\"The 18th Attic - Paranormal Anomaly Hunting Game\",\"slug\":\"the-18th-attic-paranormal-anomaly-hunting-game\",\"description\":\"\\nThe 18th Attic est un jeu d\'horreur psychologique où vous incarnez un homme piégé dans une boucle, armé seulement d\'un appareil photo instantané. Traquez les anomalies paranormales qui rôdent en les photographiant et en détectant leur présence pour percer les secrets obsédants de votre passé. Chaque photo déverrouille un nouveau souvenir.\\nParviendrez-vous à tous les découvrir ? Utilisez votre appareil photo instantané pour photographier les anomalies paranormales que vous trouvez étranges. Chaque photo déverrouille un souvenir… mais attention, elles essaieront de vous piéger, et certaines anomalies sont plus inoffensives les unes que les autres.\\n\\n\\nDétectez et capturez les anomalies paranormales et éliminez-les en les photographiant – ombres changeantes, figures spectrales et perturbations énigmatiques – tout en reconstituant le passé poignant du grenier. Chaque photo vous rapproche de ses sinistres secrets, mais les anomalies ne disparaîtront pas sans laisser de traces.\\nÉquipé d\'un appareil photo instantané et d\'un briquet, vous devez scruter votre environnement. Attention à ne pas manquer de cartouches photo, sinon vous ne pourrez pas hanter le paranormal… et prenez garde à votre santé. Certaines anomalies peuvent vous attaquer.\\n\\nPréparez-vous à affronter vos peurs les plus profondes et à mettre à l\'épreuve votre détermination et votre sens de l\'observation. Parviendrez-vous à survivre à cette boucle et à découvrir la vérité, ou le grenier vous emportera-t-il à jamais ? Grimpez au grenier.\",\"released\":\"2026-02-01\",\"background_image\":\"https://media.rawg.io/media/screenshots/9c0/9c02e150a93ec5870141f5c29923a0a1.jpg\",\"rating\":0,\"rating_top\":0,\"metacritic\":null,\"playtime\":0,\"esrb_rating\":\"Not Rated\",\"website\":\"\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}}],\"genres\":[],\"developers\":[{\"id\":42846,\"name\":\"Steelkrill Studio\",\"slug\":\"steelkrill-studio\"}],\"publishers\":[{\"id\":47275,\"name\":\"Steelkrill Studio\",\"slug\":\"steelkrill-studio\"}],\"tags\":[{\"id\":820,\"name\":\"secrets\",\"slug\":\"secrets\"},{\"id\":92376,\"name\":\"Aventure\",\"slug\":\"aventure\"}],\"screenshots\":[{\"id\":4296795,\"image\":\"https://media.rawg.io/media/screenshots/973/9730d5312ba8184cd6c692150bd6e8ce.jpg\"},{\"id\":4296796,\"image\":\"https://media.rawg.io/media/screenshots/688/688aaeb54b40f6a723045aa192a40128.jpg\"},{\"id\":4296797,\"image\":\"https://media.rawg.io/media/screenshots/aee/aee0e726df4b7e5b365ea8e68bde0f7b.jpg\"},{\"id\":4296798,\"image\":\"https://media.rawg.io/media/screenshots/81d/81d607791665b3af7d24d263fde08aae.jpg\"},{\"id\":4296799,\"image\":\"https://media.rawg.io/media/screenshots/b36/b36a0027e9dddc7a1af658417aef17e7.jpg\"},{\"id\":4296800,\"image\":\"https://media.rawg.io/media/screenshots/f86/f867727cf7037b4765f6c7f535ebe4e3.jpg\"}],\"series\":[],\"stores\":[{\"id\":1017305,\"store\":{\"id\":5,\"name\":\"GOG\",\"domain\":\"gog.com\"}}]}', '2026-01-30 11:43:23'),
(153, 6, 4200, '{\"id\":4200,\"name\":\"Portal 2\",\"slug\":\"portal-2\",\"description\":\"Portal 2 is a first-person puzzle game developed by Valve Corporation and released on April 19, 2011 on Steam, PS3 and Xbox 360. It was published by Valve Corporation in digital form and by Electronic Arts in physical form. \\n\\nIts plot directly follows the first game\'s, taking place in the Half-Life universe. You play as Chell, a test subject in a research facility formerly ran by the company Aperture Science, but taken over by an evil AI that turned upon its creators, GladOS. After defeating GladOS at the end of the first game but failing to escape the facility, Chell is woken up from a stasis chamber by an AI personality core, Wheatley, as the unkempt complex is falling apart. As the two attempt to navigate through the ruins and escape, they stumble upon GladOS, and accidentally re-activate her...\\n\\nPortal 2\'s core mechanics are very similar to the first game\'s ; the player must make their way through several test chambers which involve puzzles. For this purpose, they possess a Portal Gun, a weapon capable of creating teleportation portals on white surfaces. This seemingly simple mechanic and its subtleties coupled with the many different puzzle elements that can appear in puzzles allows the game to be easy to start playing, yet still feature profound gameplay. The sequel adds several new puzzle elements, such as gel that can render surfaces bouncy or allow you to accelerate when running on them.\\n\\nThe game is often praised for its gameplay, its memorable dialogue and writing and its aesthetic. Both games in the series are responsible for inspiring most puzzle games succeeding them, particularly first-person puzzle games. The series, its characters and even its items such as the portal gun and the companion cube have become a cultural icon within gaming communities.\\n\\nPortal 2 also features a co-op mode where two players take on the roles of robots being led through tests by GladOS, as well as an in-depth level editor.\",\"released\":\"2011-04-18\",\"background_image\":\"https://media.rawg.io/media/games/2ba/2bac0e87cf45e5b508f227d281c9252a.jpg\",\"rating\":4.58,\"rating_top\":5,\"metacritic\":95,\"playtime\":11,\"esrb_rating\":\"Everyone 10+\",\"website\":\"http://www.thinkwithportals.com/\",\"platforms\":[{\"platform\":{\"id\":16,\"name\":\"PlayStation 3\",\"slug\":\"playstation3\"}},{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":14,\"name\":\"Xbox 360\",\"slug\":\"xbox360\"}},{\"platform\":{\"id\":6,\"name\":\"Linux\",\"slug\":\"linux\"}},{\"platform\":{\"id\":5,\"name\":\"macOS\",\"slug\":\"macos\"}},{\"platform\":{\"id\":1,\"name\":\"Xbox One\",\"slug\":\"xbox-one\"}}],\"genres\":[{\"id\":2,\"name\":\"Shooter\",\"slug\":\"shooter\"},{\"id\":7,\"name\":\"Puzzle\",\"slug\":\"puzzle\"}],\"developers\":[{\"id\":1612,\"name\":\"Valve Software\",\"slug\":\"valve-software\"}],\"publishers\":[{\"id\":354,\"name\":\"Electronic Arts\",\"slug\":\"electronic-arts\"},{\"id\":3399,\"name\":\"Valve\",\"slug\":\"valve\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":7,\"name\":\"Multiplayer\",\"slug\":\"multiplayer\"},{\"id\":40836,\"name\":\"Full controller support\",\"slug\":\"full-controller-support\"},{\"id\":40849,\"name\":\"Steam Cloud\",\"slug\":\"steam-cloud\"},{\"id\":13,\"name\":\"Atmospheric\",\"slug\":\"atmospheric\"},{\"id\":7808,\"name\":\"steam-trading-cards\",\"slug\":\"steam-trading-cards\"},{\"id\":18,\"name\":\"Co-op\",\"slug\":\"co-op\"},{\"id\":118,\"name\":\"Story Rich\",\"slug\":\"story-rich\"},{\"id\":411,\"name\":\"cooperative\",\"slug\":\"cooperative\"},{\"id\":8,\"name\":\"First-Person\",\"slug\":\"first-person\"},{\"id\":32,\"name\":\"Sci-fi\",\"slug\":\"sci-fi\"},{\"id\":30,\"name\":\"FPS\",\"slug\":\"fps\"},{\"id\":9,\"name\":\"Online Co-Op\",\"slug\":\"on