(180, 1, 10206, '{\"id\":10206,\"name\":\"Ashes of the Singularity: Escalation\",\"slug\":\"ashes-of-the-singularity-escalation\",\"description\":\"The human race has expanded into the galaxy thanks to the wonders of the technological singularity.  You have become so powerful that you can manage vast armies across an entire world that provide you with an ever greater galactic empire.\\nNow, humanity is under assault by a new enemy. Calling themselves the Substrate, they seek to annihilate the human race from existence.  You, as an up and coming member of the Post-Human Coalition, must deal with both this new menace as well as renegade humans trying to lay claim to their own worlds.\\nPlay as the Post Human Coalition or their eternal foes the Substrate and battle for control of the galaxy. Experience maps of unprecedented size and detail with the unparalleled power of the world’s first native 64-bit RTS engine, Nitrous.\\nEnjoy the game online with friends in ranked or unranked multiplayer mode or play it by yourself against a powerful non-cheating AI in skirmish or campaign mode. No matter what mode you play, strategy is the key: deciding what technologies to research, where to send your armies, how to manage your economy, and what units to construct are crucial to victory.\\nExperience a massive-scale real time strategy game where you wage war across worlds with thousands of units. The conflict has escalated, and it’s time to choose a side.\",\"released\":\"2016-11-09\",\"background_image\":\"https://media.rawg.io/media/screenshots/651/651f338d5c03b8c650543629ce486a52.jpg\",\"rating\":2.41,\"rating_top\":1,\"playtime\":3,\"esrb_rating\":\"Not Rated\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}}],\"genres\":[{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-rpg\"},{\"id\":10,\"name\":\"Strategy\",\"slug\":\"strategy\"},{\"id\":14,\"name\":\"Simulation\",\"slug\":\"simulation\"},{\"id\":51,\"name\":\"Indie\",\"slug\":\"indie\"}],\"developers\":[{\"id\":3602,\"name\":\"Stardock Entertainment\",\"slug\":\"stardock-entertainment\"},{\"id\":4205,\"name\":\"Oxide Games\",\"slug\":\"oxide-games\"}],\"publishers\":[{\"id\":3319,\"name\":\"Stardock Entertainment\",\"slug\":\"stardock-entertainment\"},{\"id\":3332,\"name\":\"Stardock\",\"slug\":\"stardock\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":7,\"name\":\"Multiplayer\",\"slug\":\"multiplayer\"},{\"id\":40849,\"name\":\"Steam Cloud\",\"slug\":\"steam-cloud\"},{\"id\":7808,\"name\":\"steam-trading-cards\",\"slug\":\"steam-trading-cards\"},{\"id\":24,\"name\":\"RPG\",\"slug\":\"rpg\"},{\"id\":18,\"name\":\"Co-op\",\"slug\":\"co-op\"},{\"id\":411,\"name\":\"cooperative\",\"slug\":\"cooperative\"},{\"id\":32,\"name\":\"Sci-fi\",\"slug\":\"sci-fi\"},{\"id\":9,\"name\":\"Online Co-Op\",\"slug\":\"online-co-op\"},{\"id\":397,\"name\":\"Online multiplayer\",\"slug\":\"online-multiplayer\"},{\"id\":11669,\"name\":\"stats\",\"slug\":\"stats\"},{\"id\":25,\"name\":\"Space\",\"slug\":\"space\"},{\"id\":167,\"name\":\"Futuristic\",\"slug\":\"futuristic\"},{\"id\":168,\"name\":\"RTS\",\"slug\":\"rts\"},{\"id\":337,\"name\":\"overlay\",\"slug\":\"overlay\"},{\"id\":334,\"name\":\"achievements\",\"slug\":\"achievements\"},{\"id\":247,\"name\":\"Real Time Tactics\",\"slug\":\"real-time-tactics\"},{\"id\":296,\"name\":\"Benchmark\",\"slug\":\"benchmark\"}],\"screenshots\":[{\"id\":78273,\"image\":\"https://media.rawg.io/media/screenshots/5cc/5cc8298f412e20d131b562d2e4ab4884.jpg\"},{\"id\":78274,\"image\":\"https://media.rawg.io/media/screenshots/6d9/6d9f9d3bf11cb2e593763a935790c1c1.jpg\"},{\"id\":78275,\"image\":\"https://media.rawg.io/media/screenshots/c7c/c7cde2aa8241904294a37c041a8966f3.jpg\"},{\"id\":78276,\"image\":\"https://media.rawg.io/media/screenshots/6e7/6e70b5d3fcebc5931c8a057ff86588c4.jpg\"},{\"id\":78277,\"image\":\"https://media.ra