(181, 1, 290856, '{\"id\":290856,\"name\":\"Apex Legends\",\"slug\":\"apex-legends\",\"description\":\"Conquer with character in Apex Legends, a free-to-play* Battle Royale shooter where legendary characters with powerful abilities team up to battle for fame and fortune on the fringes of the Frontier. Master an ever-growing roster of diverse legends, deep tactical squad play, and bold new innovations that level-up the Battle Royale experience—all within a rugged world where anything goes. Welcome to the next evolution of Battle Royale.\\n\\nCharacters you can play as: Caustic, Bangalore, Bloodhound, Crypto, Gibraltar, Lifeline, Loba, Mirage, Octane, Pathfinder, Rampart, Revenant.\",\"released\":\"2019-02-04\",\"background_image\":\"https://media.rawg.io/media/games/737/737ea5662211d2e0bbd6f5989189e4f1.jpg\",\"rating\":3.63,\"rating_top\":4,\"playtime\":5,\"esrb_rating\":\"Teen\",\"platforms\":[{\"platform\":{\"id\":18,\"name\":\"PlayStation 4\",\"slug\":\"playstation4\"}},{\"platform\":{\"id\":7,\"name\":\"Nintendo Switch\",\"slug\":\"nintendo-switch\"}},{\"platform\":{\"id\":5,\"name\":\"macOS\",\"slug\":\"macos\"}},{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":1,\"name\":\"Xbox One\",\"slug\":\"xbox-one\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":2,\"name\":\"Shooter\",\"slug\":\"shooter\"}],\"developers\":[{\"id\":19732,\"name\":\"Respawn Entertainment\",\"slug\":\"respawn-entertainment\"}],\"publishers\":[{\"id\":354,\"name\":\"Electronic Arts\",\"slug\":\"electronic-arts\"}],\"tags\":[{\"id\":7,\"name\":\"Multiplayer\",\"slug\":\"multiplayer\"},{\"id\":40836,\"name\":\"Full controller support\",\"slug\":\"full-controller-support\"},{\"id\":13,\"name\":\"Atmospheric\",\"slug\":\"atmospheric\"},{\"id\":18,\"name\":\"Co-op\",\"slug\":\"co-op\"},{\"id\":8,\"name\":\"First-Person\",\"slug\":\"first-person\"},{\"id\":32,\"name\":\"Sci-fi\",\"slug\":\"sci-fi\"},{\"id\":30,\"name\":\"FPS\",\"slug\":\"fps