(183, 1, 29028, '{\"id\":29028,\"name\":\"Metro 2033\",\"slug\":\"metro-2033\",\"description\":\"Not all post-apocalyptic stories begin in the burned wastelands, this time nuclear and chemical locked up survivors in the Moscow Subway, and player will take the place of Artyom, one of the survivors from the VDNKh, adoptive son of the station commander, and taking upon himself the task to deliver information about the Dark Ones to the Polis, the capital of subway, after the special operative from Spartans named Hunter went missing, after he ventured to gather information on the Hive – living space of the Dark Ones.\\r\\nDark tunnels of broken subway create a claustrophobic atmosphere, where good and bad people alike are forced to bond. Closely following original book, Metro 2033 introducing bullets as currency. Players can exchange one type of bullets for another one, but it’s still ammo and will be wasted with inaccurate aim. It’s a first person shooter that will allow players not only see how broken apart can society become but to explore such society and ruins of the city above the underground settlement. Various monsters and mutants are not the only threat to the players, but humans as well. FPS with some stealth sections, Metro 2033 will show you every historical enemy type: bandits, Communists, and Nazis.\",\"released\":\"2010-03-16\",\"background_image\":\"https://media.rawg.io/media/games/120/1201a40e4364557b124392ee50317b99.jpg\",\"rating\":3.94,\"rating_top\":4,\"playtime\":2,\"esrb_rating\":\"Mature\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":14,\"name\":\"Xbox 360\",\"slug\":\"xbox360\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":2,\"name\":\"Shooter\",\"slug\":\"shooter\"}],\"developers\":[{\"id\":4304,\"name\":\"4A Games\",\"slug\":\"4a-games\"}],\"publishers\":[{\"id\":311,\"name\":\"Deep Silver\",\"slug\":\"deep-silver\"},{\"id\":6062,\"name\":\"THQ\",\"slug\":\"thq\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":40836,\"name\":\"Full controller support\",\"slug\":\"full-controller-support\"},{\"id\":40849,\"name\":\"Steam Cloud\",\"slug\":\"steam-cloud\"},{\"id\":13,\"name\":\"Atmospheric\",\"slug\":\"atmospheric\"},{\"id\":42,\"name\":\"Great Soundtrack\",\"slug\":\"great-soundtrack\"},{\"id\":118,\"name\":\"Story Rich\",\"slug\":\"story-rich\"},{\"id\":8,\"name\":\"First-Person\",\"slug\":\"first-person\"},{\"id\":32,\"name\":\"Sci-fi\",\"slug\":\"sci-fi\"},{\"id\":16,\"name\":\"Horror\",\"slug\":\"horror\"},{\"id\":30,\"name\":\"FPS\",\"slug\":\"fps\"},{\"id\":1,\"name\":\"Survival\",\"slug\":\"survival\"},{\"id\":15,\"name\":\"Stealth\",\"slug\":\"stealth\"},{\"id\":41,\"name\":\"Dark\",\"slug\":\"dark\"},{\"id\":17,\"name\":\"Survival Horror\",\"slug\":\"survival-horror\"},{\"id\":43,\"name\":\"Post-apocalyptic\",\"slug\":\"post-apocalyptic\"},{\"id\":305,\"name\":\"Linear\",\"slug\":\"linear\"},{\"id\":133,\"name\":\"3D Vision\",\"slug\":\"3d-vision\"},{\"id\":283,\"name\":\"Based On A Novel\",\"slug\":\"based-on-a-novel\"},{\"id\":296,\"name\":\"Benchmark\",\"slug\":\"benchmark\"}],\"screenshots\":[{\"id\":462425,\"image\":\"https://media.rawg.io/media/screenshots/e79/e7946cab379370fdef03c2e2c9dfcce3.jpg\"},{\"id\":462426,\"image\":\"https://media.rawg.io/media/screenshots/ad4/ad433938bd2377b1beaa8a184bb67405.jpg\"},{\"id\":462427,\"image\":\"https://media.rawg.io/media/screenshots/28e/28e63b7f13e9ec24ad64ef5ae75e258c.jpg\"},{\"id\":462428,\"image\":\"https://media.rawg.io/media/screenshots/b99/b99a0bf0f09991d76ad13c65f7e64562.jpg\"},{\"id\":462429,\"image\":\"https://media.rawg.io/media/screenshots/df1/df1aa556c727ad4f4753dbb9e43875c0.jpg\"},{\"id\":462430,\"image\":\"https://media.rawg.io/media/screenshots/94b/94bcd09e75c34712fa85ea6b4945a57c.jpg\"}],\"series\":[{\"id\":28201,\"name\":\"Metro Exodus\",\"slug\":\"metro-exodus\"},{\"id\":5938,\"name\":\"Metro 2033: Wars\",\"slug\":\"metro-2033-wars\"},{\"id\":28395,\"name\":\"Metro: Last Light\",\"slug\":\"metro-last-light\"}],\"stores\":[{\"id\":255112,\"store\":{\"id\":1,\"name\":\"Steam\",\"domain\":\"store.steampowered.com\"}},{\"id\":34644,\"store\":{\"id\":7,\"name\":\"Xbox 360 Store\",\"domain\":\"marketplace.xbox.com\"}}]}', '2026-01-31 04:29:24'),
(184, 1, 139716, '{\"id\":139716,\"name\":\"Winter Memories (itch)\",\"slug\":\"winter-memories\",\"description\":\"Tricia, an adventurous young girl, lost the love of her life. On the winter solstice of every year, she goes to visit his grave. But, this year - she is met with a nasty surprise! What is this nasty surprise, and how will Tricia deal with it?! Play to find out! WARNING: Strong language, mention of death.\\nThis is the very first game I ever completed/released. It\'s just a simple puzzle game (with some battles thrown in). I hope you enjoy~\",\"released\":\"2018-06-07\",\"background_image\":\"https://media.rawg.io/media/screenshots/9ed/9ed2986b18bd97e5ab361b106ee43cad.jpg\",\"rating\":0,\"rating_top\":0,\"playtime\":0,\"esrb_rating\":\"Not Rated\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}}],\"genres\":[{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-rpg\"}],\"developers\":[{\"id\":63639,\"name\":\"raymi100 Games\",\"slug\":\"raymi100-games\"}],\"publishers\":[],\"tags\":[{\"id\":662,\"name\":\"RPG Maker\",\"slug\":\"rpg-maker\"}],\"screenshots\":[{\"id\":1160977,\"image\":\"https://media.rawg.io/media/screenshots/8f6/8f67c96f5c7f3ce715fa712d418cf27c.jpg\"},{\"id\":1160979,\"image\":\"https://media.rawg.io/media/screenshots/061/061b565e2441dd4fbd0cb8b6208fbc09.jpg\"},{\"id\":1160981,\"image\":\"https://media.rawg.io/media/screenshots/164/164c0d4310411fcadbb41b0cd04ea5bf.jpg\"},{\"id\":1160982,\"image\":\"https://media.rawg.io/media/screenshots/8a2/8a2d9b888e0df1b0a4cc77ddcb23e747.jpg\"},{\"id\":1160983,\"image\":\"https://media.rawg.io/media/screenshots/9ed/9ed2986b18bd97e5ab361b106ee43cad.jpg\"}],\"series\":[],\"stores\":[{\"id\":131543,\"store\":{\"id\":9,\"name\":\"itch.io\",\"domain\":\"itch.io\"}}]}', '2026-01-31 06:02:58'),
(185, 1, 536886, '{\"id\":536886,\"name\":\"The Binding of Isaac: Repentance\",\"slug\":\"the-binding-of-isaac-repentance\",\"description\":\"Experience the modern classic, The Binding of Isaac, like you\'ve never seen it before. It\'s a game too big to be called a sequel: Repentance takes Isaac to new heights of roguelike dungeon adventure, as the brave boy descends into the basement for his greatest challenge yet! Isaac\'s new quest takes him to unknown places he\'s never been, filled with horrible new enemies and bosses, weapon combos you\'ve never synergized before and items he\'s never seen... unholy terrors from his wildest dreams and worst nightmares!\",\"released\":\"2021-03-31\",\"background_image\":\"https://media.rawg.io/media/screenshots/f76/f76b46caccc642a46fa7e9ef7406b38b.jpg\",\"rating\":4.69,\"rating_top\":5,\"playtime\":0,\"esrb_rating\":\"Not Rated\",\"platforms\":[{\"platform\":{\"id\":187,\"name\":\"PlayStation 5\",\"slug\":\"playstation5\"}},{\"platform\":{\"id\":18,\"name\":\"PlayStation 4\",\"slug\":\"playstation4\"}},{\"platform\":{\"id\":7,\"name\":\"Nintendo Switch\",\"slug\":\"nintendo-switch\"}},{\"platform\":{\"id\":186,\"name\":\"Xbox Series S/X\",\"slug\":\"xbox-series-x\"}},{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":1,\"name\":\"Xbox One\",\"slug\":\"xbox-one\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"}],\"developers\":[{\"id\":498,\"name\":\"Nicalis\",\"slug\":\"nicalis\"}],\"publishers\":[{\"id\":725,\"name\":\"Nicalis\",\"slug\":\"nicalis\"}],\"tags\":[],\"screenshots\":[{\"id\":2652398,\"image\":\"https://media.rawg.io/media/screenshots/c78/c785c357d4296f883eafa8cc662b2476.jpg\"},{\"id\":2652399,\"image\":\"https://media.rawg.io/media/screenshots/0fe/0fe17acda3ed35e8da67c1faf15c8006.jpg\"},{\"id\":2652400,\"image\":\"https://media.rawg.io/media/screenshots/e43/e4383d4adc77a81bb6a2511f28cf0d1c.jpg\"},{\"id\":2652401,\"image\":\"https://media.rawg.io/media/screenshots/0f0/0f0207627cf9a5b14e5ce9dc12bd86ef.jpg\"},{\"id\":2652402,\"image\":\"https://media.rawg.io/media/screenshots/d73/d73852eae5c167ee6913fd3f3943d8ec.jpg\"},{\"id\":2652403,\"image\":\"https://media.rawg.io/media/screenshots/cae/cae3fe6a7f40e3f19b34a9703d503d4b.jpg\"}],\"series\":[{\"id\":23742,\"name\":\"The Binding of Isaac: Afterbirth+\",\"slug\":\"the-binding-of-isaac-afterbirth\"}],\"stores\":[{\"id\":529851,\"store\":{\"id\":1,\"name\":\"Steam\",\"domain\":\"store.steampowered.com\"}},{\"id\":579970,\"store\":{\"id\":11,\"name\":\"Epic Games\",\"domain\":\"epicgames.com\"}},{\"id\":674667,\"store\":{\"id\":2,\"name\":\"Xbox Store\",\"domain\":\"microsoft.com\"}}]}', '2026-01-31 06:03:14'),
(186, 1, 13910, '{\"id\":13910,\"name\":\"XCOM: Enemy Unknown\",\"slug\":\"xcom-enemy-unknown\",\"description\":\"Any alien invasion meets resistance in some form, so in this reboot of the series, players will take the mantle of the XCOM commander, and control the elite scientists and soldiers, in order to stop the threat. After successfully neutralizing scout ships, securing the crash site and retrieving civilians, XCOM personnel, and alien corpses, it’s clear that all of them are genetically and cybernetically altered, which starts the beginning of the arms race with the invaders.\\r\\nDuring the missions X-COM: Enemy Unknown is a turn-based tactical game, while in the downtime players will direct the organization, form units, oversee the research, expand the base of operations and manage resources. Complex combat consists of units taking turns to perform their actions with a top-down view of the battlefield. XCOM soldiers and aliens can take cover during battles, and miss their shots and attacks if anything affects their accuracy. Over the course of the game, players will be able to gain access to new technology while encountering new varied enemy types.\",\"released\":\"2012-10-09\",\"background_image\":\"https://media.rawg.io/media/games/238/2383a172b4d50a7b44e07980eb7141ea.jpg\",\"rating\":4.2,\"rating_top\":4,\"playtime\":13,\"esrb_rating\":\"Not Rated\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":21,\"name\":\"Android\",\"slug\":\"android\"}},{\"platform\":{\"id\":3,\"name\":\"iOS\",\"slug\":\"ios\"}},{\"platform\":{\"id\":14,\"name\":\"Xbox 360\",\"slug\":\"xbox360\"}},{\"platform\":{\"id\":16,\"name\":\"PlayStation 3\",\"slug\":\"playstation3\"}},{\"platform\":{\"id\":5,\"name\":\"macOS\",\"slug\":\"macos\"}}],\"genres\":[{\"id\":10,\"name\":\"Strategy\",\"slug\":\"strategy\"}],\"developers\":[{\"id\":18893,\"name\":\"Feral Interactive\",\"slug\":\"feral-interactive\"},{\"id\":383,\"name\":\"2K\",\"slug\":