(187, 1, 400292, '{\"id\":400292,\"name\":\"Zone of the Enders 2: The Second Runner\",\"slug\":\"zone-of-the-enders-2-the-second-runner\",\"description\":\"Zone of the Enders: The 2nd Runner, known in Japan as Anubis: Zone of the Enders ,is a third-person shooter hack and slash video game that was developed and published by Konami for the PlayStation 2 in 2003. The sequel to Zone of the Enders is based around mecha combat with the player once again controlling the \\\"Orbital Frame\\\" Jehuty. Unlike its predecessor, the game is now centered on action elements with the player not needing to protect civilians in need and instead Jehuty contains more weaponry than in the previous game. (From Wikipedia)\",\"released\":\"2003-02-13\",\"background_image\":\"https://media.rawg.io/media/screenshots/91c/91c7cd98fadf1919d97d7142eb9d4718.jpg\",\"rating\":4.5,\"rating_top\":5,\"playtime\":0,\"esrb_rating\":\"Mature\",\"platforms\":[{\"platform\":{\"id\":15,\"name\":\"PlayStation 2\",\"slug\":\"playstation2\"}},{\"platform\":{\"id\":16,\"name\":\"PlayStation 3\",\"slug\":\"playstation3\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":14,\"name\":\"Simulation\",\"slug\":\"simulation\"}],\"developers\":[{\"id\":15598,\"name\":\"Konami Computer Entertainment Japan\",\"slug\":\"konami-computer-entertainment-japan\"}],\"publishers\":[{\"id\":10691,\"name\":\"Konami\",\"slug\":\"konami\"}],\"tags\":[],\"screenshots\":[{\"id\":2371077,\"image\":\"https://media.rawg.io/media/screenshots/a9a/a9a2516f0670c8e29119cedd95103170.jpg\"},{\"id\":2371078,\"image\":\"https://media.rawg.io/media/screenshots/982/982b979d4d712d5b070c0847ae5cc926.jpg\"},{\"id\":2371079,\"image\":\"https://media.rawg.io/media/screenshots/91c/91c7cd98fadf1919d97d7142eb9d4718.jpg\"}],\"series\":[{\"id\":58388,\"name\":\"ZONE OF THE ENDERS: The 2nd Runner - M∀RS\",\"slug\":\"zone-of-the-enders-the-2nd-runner-mrs\"},{\"id\":4117,\"name\":\"Zone of the Enders HD Collection\",\"slug\":\"zone-of-the-enders-hd-collection\"},{\"id\":53654,\"name\":\"Zone of the Enders: The Fist of Mars\",\"slug\":\"zone-of-the-enders-the-fist-of-mars\"},{\"id\":371824,\"name\":\"Zone of the Enders\",\"slug\":\"zone-of-the-enders\"}],\"stores\":[]}', '2026-01-31 06:12:31'),
(188, 1, 58824, '{\"id\":58824,\"name\":\"Xenoblade Chronicles 2: Torna ~ The Golden Country\",\"slug\":\"xenoblade-chronicles-2-torna-the-golden-country\",\"description\":\"Guide a group of legendary warriors on a journey through the tragic history that doomed a kingdom and drove a hero down a dark path 500 years before the events of the Xenoblade Chronicles™ 2 game. Defend yourself from Malos and his forces using all the fury of this refined battle system, allowing you to fight as both the artificial lifeforms known as Blades and their masters, the Drivers.\\nDoes not include the main Xenoblade Chronicles 2 game.\\nBoth the retail and digital editions contain a download code for packs 1-4 of the Xenoblade Chronicles 2 Expansion Pass. Expansion Pass only playable with the main Xenoblade Chronicles 2 game (sold separately).\",\"released\":\"2018-09-14\",\"background_image\":\"https://media.rawg.io/media/screenshots/35b/35b514c99b084d6b14ceb37181113645.jpg\",\"rating\":4.37,\"rating_top\":5,\"playtime\":0,\"esrb_rating\":\"Teen\",\"platforms\":[{\"platform\":{\"id\":7,\"name\":\"Nintendo Switch\",\"slug\":\"nintendo-switch\"}}],\"genres\":[{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-rpg\"}],\"developers\":[{\"id\":27291,\"name\":\"Monolith Soft\",\"slug\":\"monolith-soft\"}],\"publishers\":[{\"id\":10681,\"name\":\"Nintendo\",\"slug\":\"nintendo\"}],\"tags\":[{\"id\":468,\"name\":\"role-playing\",\"slug\":\"role-playing\"}],\"screenshots\":[{\"id\":779331,\"image\":\"https://media.rawg.io/media/screenshots/3fb/3fbafd7e8049a601f91f3b17dff6ec07.jpg\"},{\"id\":779332,\"image\":\"https://media.rawg.io/media/screenshots/20f/20fd1d3fb904d47d05f35e8d06ab7cb1.jpg\"},{\"id\":779333,\"image\":\"https://media.rawg.io/media/screenshots/cd0/cd09cb50e6c0e0ec836ee201a371a921.jpeg\"},{\"id\":779334,\"image\":\"https://media.rawg.io/media/screenshots/faf/fafe86a13dbc31628065158862371696.jpg\"},{\"id\":779335,\"image\":\"https://media.rawg.io/media/screenshots/7fb/7fb03fb9fcc8e61cb6fe5bbc2cd454dc.jpg\"},{\"id\":779336,\"image\":\"https://media.rawg.io/media/screenshots/35b/35b514c99b084d6b14ceb37181113645.jpg\"}],\"series\":[],\"stores\":[{\"id\":48900,\"store\":{\"id\":6,\"name\":\"Nintendo Store\",\"domain\":\"nintendo.com\"}}]}', '2026-01-31 06:13:28');
