(190, 1, 58781, '{\"id\":58781,\"name\":\"The Elder Scrolls VI\",\"slug\":\"the-elder-scrolls-vi\",\"description\":\"Currently in pre-production at Bethesda Game Studios, the acclaimed developers of Skyrim and Fallout 4. The highly-anticipated next chapter in the iconic The Elder Scrolls series.\",\"released\":null,\"background_image\":\"https://media.rawg.io/media/games/b40/b40eba32d8715d5fdf9634939fe0eca3.jpg\",\"rating\":4.86,\"rating_top\":5,\"playtime\":0,\"esrb_rating\":\"Not Rated\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":186,\"name\":\"Xbox Series S/X\",\"slug\":\"xbox-series-x\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":5,\"name\":\"RPG\",\"slug\":\"role-playing-games-rpg\"}],\"developers\":[{\"id\":4207,\"name\":\"Bethesda Game Studios\",\"slug\":\"bethesda-game-studios\"}],\"publishers\":[{\"id\":339,\"name\":\"Bethesda Softworks\",\"slug\":\"bethesda-softworks\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":13,\"name\":\"Atmospheric\",\"slug\":\"atmospheric\"},{\"id\":24,\"name\":\"RPG\",\"slug\":\"rpg\"},{\"id\":36,\"name\":\"Open World\",\"slug\":\"open-world\"},{\"id\":8,\"name\":\"First-Person\",\"slug\":\"first-person\"},{\"id\":64,\"name\":\"Fantasy\",\"slug\":\"fantasy\"},{\"id\":6,\"name\":\"Exploration\",\"slug\":\"exploration\"},{\"id\":69,\"name\":\"Action-Adventure\",\"slug\":\"action-adventure\"},{\"id\":478,\"name\":\"3rd-Person Perspective\",\"slug\":\"3rd-person-perspective\"},{\"id\":215,\"name\":\"Dragons\",\"slug\":\"dragons\"},{\"id\":324,\"name\":\"Experience\",\"slug\":\"experience\"}],\"screenshots\":[{\"id\":778978,\"image\":\"https://media.rawg.io/media/screenshots/b73/b73f234a3d953c7e822c2ef5e54c309f.jpg\"}],\"series\":[{\"id\":1001843,\"name\":\"The Elder Scrolls IV: Oblivion Remastered\",\"slug\":\"the-elder-scrolls-iv-oblivion-remastered\"},{\"id\":71560,\"name\":\"The Elder Scrolls: Blades\",\"slug\":\