(7, 1, 29028, '{\"id\":29028,\"name\":\"Metro 2033\",\"slug\":\"metro-2033\",\"description\":\"Not all post-apocalyptic stories begin in the burned wastelands, this time nuclear and chemical locked up survivors in the Moscow Subway, and player will take the place of Artyom, one of the survivors from the VDNKh, adoptive son of the station commander, and taking upon himself the task to deliver information about the Dark Ones to the Polis, the capital of subway, after the special operative from Spartans named Hunter went missing, after he ventured to gather information on the Hive – living space of the Dark Ones.\\r\\nDark tunnels of broken subway create a claustrophobic atmosphere, where good and bad people alike are forced to bond. Closely following original book, Metro 2033 introducing bullets as currency. Players can exchange one type of bullets for another one, but it’s still ammo and will be wasted with inaccurate aim. It’s a first person shooter that will allow players not only see how broken apart can society become but to explore such society and ruins of the city above the underground settlement. Various monsters and mutants are not the only threat to the players, but humans as well. FPS with some stealth sections, Metro 2033 will show you every historical enemy type: bandits, Communists, and Nazis.\",\"released\":\"2010-03-16\",\"background_image\":\"https://media.rawg.io/media/games/120/1201a40e4364557b124392ee50317b99.jpg\",\"rating\":3.94,\"rating_top\":4,\"playtime\":2,\"esrb_rating\":\"Mature\",\"platforms\":[{\"platform\":{\"id\":4,\"name\":\"PC\",\"slug\":\"pc\"}},{\"platform\":{\"id\":14,\"name\":\"Xbox 360\",\"slug\":\"xbox360\"}}],\"genres\":[{\"id\":4,\"name\":\"Action\",\"slug\":\"action\"},{\"id\":2,\"name\":\"Shooter\",\"slug\":\"shooter\"}],\"developers\":[{\"id\":4304,\"name\":\"4A Games\",\"slug\":\"4a-games\"}],\"publishers\":[{\"id\":311,\"name\":\"Deep Silver\",\"slug\":\"deep-silver\"},{\"id\":6062,\"name\":\"THQ\",\"slug\":\"thq\"}],\"tags\":[{\"id\":31,\"name\":\"Singleplayer\",\"slug\":\"singleplayer\"},{\"id\":40847,\"name\":\"Steam Achievements\",\"slug\":\"steam-achievements\"},{\"id\":40836,\"name\":\"Full controller support\",\"slug\":\"full-controller-support\"},{\"id\":40849,\"name\":\"Steam Cloud\",\"slug\":\"steam-cloud\"},{\"id\":13,\"name\":\"Atmospheric\",\"slug\":\"atmospheric\"},{\"id\":42,\"name\":\"Great Soundtrack\",\"slug\":\"great-soundtrack\"},{\"id\":118,\"name\":\"Story Rich\",\"slug\":\"story-rich\"},{\"id\":8,\"name\":\"First-Person\",\"slug\":\"first-person\"},{\"id\":32,\"name\":\"Sci-fi\",\"slug\":\"sci-fi\"},{\"id\":16,\"name\":\"Horror\",\"slug\":\"horror\"},{\"id\":30,\"name\":\"FPS\",\"slug\":\"fps\"},{\"id\":1,\"name\":\"Survival\",\"slug\":\"survival\"},{\"id\":15,\"name\":\"Stealth\",\"slug\":\"stealth\"},{\"id\":41,\"name\":\"Dark\",\"slug\":\"dark\"},{\"id\":17,\"name\":\"Survival Horror\",\"slug\":\"survival-horror\"},{\"id\":43,\"name\":\"Post-apocalyptic\",\"slug\":\"post-apocalyptic\"},{\"id\":305,\"name\":\"Linear\",\"slug\":\"linear\"},{\"id\":133,\"name\":\"3D Vision\",\"slug\":\"3d-vision\"},{\"id\":283,\"name\":\"Based On A Novel\",\"slug\":\"based-on-a-novel\"},{\"id\":296,\"name\":\"Benchmark\",\"slug\":\"benchmark\"}],\"screenshots\":[{\"id\":462425,\"image\":\"https://media.rawg.io/media/screenshots/e79/e7946cab379370fdef03c2e2c9dfcce3.jpg\"},{\"id\":462426,\"image\":\"https://media.rawg.io/media/screenshots/ad4/ad433938bd2377b1beaa8a184bb67405.jpg\"},{\"id\":462427,\"image\":\"https://media.rawg.io/media/screenshots/28e/28e63b7f13e9ec24ad64ef5ae75e258c.jpg\"},{\"id\":462428,\"image\":\"https://media.rawg.io/media/screenshots/b99/b99a0bf0f09991d76ad13c65f7e64562.jpg\"},{\"id\":462429,\"image\":\"https://media.rawg.io/media/screenshots/df1/df1aa556c727ad4f4753dbb9e43875c0.jpg\"},{\"id\":462430,\"image\":\"https://media.rawg.io/media/screenshots/94b/94bcd09e75c34712fa85ea6b4945a57c.jpg\"}],\"series\":[{\"id\":28201,\"name\":\"Metro Exodus\",\"slug\"